from manim import *
from forge.beats import ForgeScene, beat

class SigmoidExplainer(ForgeScene):
    @beat("Introduce the sigmoid function and its formula.", seconds=4, narration="Have you ever wondered how neural networks turn any number into a probability? Meet the sigmoid function.")
    def intro(self):
        title = Tex(r"$\sigma(x) = \frac{1}{1 + e^{-x}}$", font_size=48, color=BLUE_C)
        title.to_edge(UP, buff=0.8)

        self.axes = Axes(
            x_range=[-6, 6, 2],
            y_range=[-0.2, 1.2, 0.5],
            x_length=9,
            y_length=4.5,
            axis_config={"color": GREY, "include_numbers": True, "font_size": 24}
        ).shift(DOWN * 0.5)

        self.play(Write(title), run_time=1.5)
        self.play(Create(self.axes), run_time=2.0)

    @beat("Plot the sigmoid curve showing the S-shape.", seconds=4, narration="When we graph this function, we get a smooth, S-shaped curve that gracefully rises from left to right.")
    def draw_curve(self):
        self.curve = self.axes.plot(
            lambda x: 1 / (1 + np.exp(-x)),
            color=YELLOW_C,
            stroke_width=4
        )
        curve_label = Tex(r"$y = \sigma(x)$", color=YELLOW_C, font_size=36)
        curve_label.next_to(self.curve, UP + RIGHT, buff=0.2)

        self.play(Create(self.curve), Write(curve_label), run_time=3.0)

    @beat("Highlight the lower horizontal asymptote at zero.", seconds=4, narration="As our input drops to negative infinity, the output gets infinitely close to zero, but never quite reaches it.")
    def lower_bound(self):
        dashed_line_0 = DashedLine(
            start=self.axes.c2p(-6, 0),
            end=self.axes.c2p(6, 0),
            color=RED_C,
            dash_length=0.1
        )
        label_0 = MathTex("y = 0", color=RED_C, font_size=32).to_edge(LEFT).shift(DOWN * 1.5)

        self.play(Create(dashed_line_0), Write(label_0), run_time=3.0)

    @beat("Highlight the upper horizontal asymptote at one.", seconds=4, narration="Conversely, as the input grows to positive infinity, the output levels off and approaches one.")
    def upper_bound(self):
        dashed_line_1 = DashedLine(
            start=self.axes.c2p(-6, 1),
            end=self.axes.c2p(6, 1),
            color=GREEN_C,
            dash_length=0.1
        )
        label_1 = MathTex("y = 1", color=GREEN_C, font_size=32).to_edge(LEFT).shift(UP * 1.5)

        self.play(Create(dashed_line_1), Write(label_1), run_time=3.0)

    @beat("Demonstrate squashing a massive input range into the 0-1 interval.", seconds=4, narration="No matter how massive your input is—positive or negative—sigmoid squashes it entirely into a clean probability between zero and one.")
    def summary_squash(self):
        tracker = ValueTracker(0)

        dot = Dot(color=PINK).add_updater(
            lambda m: m.move_to(self.axes.c2p(tracker.get_value(), 1 / (1 + np.exp(-tracker.get_value()))))
        )

        line_to_y = always_redraw(
            lambda: DashedLine(
                start=self.axes.c2p(0, 1 / (1 + np.exp(-tracker.get_value()))),
                end=dot.get_center(),
                color=PINK,
                stroke_width=2
            )
        )

        coord_label = always_redraw(
            lambda: DecimalNumber(
                1 / (1 + np.exp(-tracker.get_value())),
                num_decimal_places=3,
                color=PINK,
                font_size=32
            ).next_to(dot, UP, buff=0.2)
        )

        self.add(dot, line_to_y, coord_label)
        self.play(tracker.animate.set_value(5), run_time=1.8)
        self.play(tracker.animate.set_value(-5), run_time=1.8)
