from fractions import Fraction
from manim import *
from forge.beats import ForgeScene, beat


class SqrtTwoIrrational(ForgeScene):

    @beat(
        "Introduce the premise by assuming root 2 can be written as a fraction in lowest terms.",
        seconds=4,
        narration="Suppose, just for a moment, that the square root of two could be written as a fraction, a over b, in its absolute simplest terms.",
    )
    def introduce_fraction(self):
        self.eq1 = MathTex(
            r"\sqrt{2} = \frac{a}{b}", font_size=54
        ).shift(UP * 2)
        self.note = Text(
            "Assume a and b share no common factors",
            font_size=24,
            color=GRAY,
        ).next_to(self.eq1, DOWN, buff=0.3)

        self.play(Write(self.eq1), FadeIn(self.note, shift=DOWN * 0.2))
        self.wait(1.0)

    @beat(
        "Square both sides to eliminate the square root.",
        seconds=4,
        narration="If we square both sides of this equation, the square root vanishes, leaving us with two equals a squared over b squared.",
    )
    def square_both_sides(self):
        self.eq2 = MathTex(
            r"2 = \frac{a^2}{b^2}", font_size=54
        ).move_to(self.eq1)
        self.play(TransformMatchingTex(self.eq1, self.eq2), FadeOut(self.note))
        self.wait(1.0)

    @beat(
        "Rearrange into a multiplication statement.",
        seconds=4,
        narration="Multiplying both sides by b squared tells us something profound: two times b squared equals a squared.",
    )
    def rearrange(self):
        self.eq3 = MathTex(
            r"2b^2 = \frac{a^2}{b^2} \cdot b^2", font_size=48
        ).shift(UP * 2)
        self.eq4 = MathTex(r"2b^2 = a^2", font_size=54).move_to(self.eq3)

        self.play(TransformMatchingTex(self.eq2, self.eq3))
        self.play(TransformMatchingTex(self.eq3, self.eq4))

        self.implication = Text(
            "This means a² must be an even number.",
            font_size=28,
            color=YELLOW,
        ).next_to(self.eq4, DOWN, buff=0.5)
        self.play(FadeIn(self.implication, shift=DOWN * 0.2))
        self.wait(1.0)

    @beat(
        "Show that a itself must also be even.",
        seconds=4,
        narration="And if a squared is even, then a itself must be even. So we can write a as two times some integer k.",
    )
    def deduction(self):
        self.eq5 = MathTex(r"a \text{ is even} \implies a = 2k", font_size=48).next_to(
            self.implication, DOWN, buff=0.5
        )
        self.play(Write(self.eq5))
        self.wait(1.5)

    @beat(
        "Conclude the contradiction.",
        seconds=4,
        narration="Substituting this back in shows b must also be even. But if both a and b are even, our fraction wasn't in lowest terms after all—a contradiction!",
    )
    def contradiction(self):
        # Compute exact count to satisfy rule 3
        conclusion_text = (
            "Contradiction: both a and b are even, violating lowest terms!"
        )
        self.conclusion = Text(
            conclusion_text, font_size=26, color=RED
        ).to_edge(DOWN, buff=0.8)

        # Clean up previous items slightly
        everything = VGroup(
            self.eq4, self.implication, self.eq5
        )
        self.play(
            everything.animate.scale(0.8).to_edge(UP, buff=0.5),
            FadeIn(self.conclusion, shift=UP * 0.2),
        )
        self.wait(2.0)
