from manim import *
from forge.beats import ForgeScene, beat
from fractions import Fraction

class IrrationalityOfRootTwo(ForgeScene):
    @beat("Introduce the assumption", seconds=4, narration="Let's assume, for a moment, that the square root of two is a rational number.")
    def assume_rational(self):
        self.eq = MathTex(r"\sqrt{2} = \frac{p}{q}").scale(1.5)
        self.cond = Text("p, q are integers, q ≠ 0", font_size=30).next_to(self.eq, DOWN)
        self.play(Write(self.eq))
        self.play(FadeIn(self.cond))

    @beat("Simplify the fraction", seconds=5, narration="We can assume this fraction is in simplest form, meaning p and q share no common factors.")
    def simplest_form(self):
        self.simple = Text("Assume p/q is fully reduced", font_size=30, color=YELLOW).next_to(self.cond, DOWN)
        self.play(Write(self.simple))
        self.wait(2)

    @beat("Square both sides", seconds=4, narration="If we square both sides, we get two equals p squared over q squared.")
    def square_sides(self):
        self.eq2 = MathTex(r"2 = \frac{p^2}{q^2}").scale(1.5)
        self.play(Transform(self.eq, self.eq2))

    @beat("Rearrange the equation", seconds=4, narration="Multiplying by q squared tells us that p squared must be two times q squared.")
    def rearrange(self):
        self.eq3 = MathTex(r"p^2 = 2q^2").scale(1.5)
        self.play(Transform(self.eq, self.eq3))
        self.play(FadeOut(self.cond, self.simple))

    @beat("Deduce p is even", seconds=5, narration="Since p squared is two times something, p squared must be even. This implies that p itself must be even.")
    def p_is_even(self):
        self.p_even = Text("p^2 is even → p is even", font_size=36, color=BLUE).to_edge(RIGHT)
        self.play(Write(self.p_even))

    @beat("Substitute p", seconds=5, narration="If p is even, we can write it as two times some integer k. Plugging this in gives us four k squared equals two q squared.")
    def substitute(self):
        sub = MathTex(r"(2k)^2 = 2q^2 \implies 4k^2 = 2q^2").scale(1.2)
        self.play(Transform(self.eq, sub))

    @beat("Deduce q is even", seconds=5, narration="Dividing by two, we find that q squared is two times k squared. This means q must also be even.")
    def q_is_even(self):
        self.q_even = Text("q^2 is even → q is even", font_size=36, color=RED).next_to(self.p_even, DOWN)
        self.play(Write(self.q_even))

    @beat("Identify the contradiction", seconds=6, narration="But wait! We said p and q had no common factors. Now we've proven both are even, meaning they share a factor of two.")
    def contradiction(self):
        self.contradiction_text = Text("Contradiction!", font_size=48, color=YELLOW).center()
        self.play(FadeIn(self.contradiction_text))
        self.play(Indicate(self.p_even), Indicate(self.q_even))

    @beat("Final conclusion", seconds=5, narration="Since our initial assumption leads to a contradiction, the square root of two cannot be written as a fraction. It is irrational.")
    def conclusion(self):
        final = MathTex(r"\sqrt{2} \notin \mathbb{Q}").scale(2).set_color(RED)
        self.play(FadeOut(self.eq, self.p_even, self.q_even, self.contradiction_text))
        self.play(Write(final))
